package com.railyatra.railway.controller;
import java.time.LocalDate; import jakarta.validation.constraints.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import com.railyatra.railway.dto.AvailabilityResponse; import com.railyatra.railway.service.AvailabilityService;
@RestController @RequestMapping("/api/availability") public class AvailabilityController {private final AvailabilityService service;public AvailabilityController(AvailabilityService service){this.service=service;}@GetMapping public AvailabilityResponse get(@RequestParam("trainNumber") @Pattern(regexp="^[A-Za-z0-9]{2,10}$") String trainNumber,@RequestParam("date") @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date,@RequestParam("class") @Pattern(regexp="^[A-Za-z0-9]{1,8}$") String classCode,@RequestParam(required=false,name="quota") String quota){return service.availability(trainNumber,date,classCode,quota);}}
